"""Robot profiles of the FORGE server: which robot (arm + gripper) the simulation uses.

ONE field of the task YAML chooses it (default "franka": exactly the behaviour before this file existed):

    robot: "franka"             FORGE's own Franka + Franka Hand (franka_mimic.usd)
    robot: "robotiq_2f85"       Franka arm + Robotiq 2F-85, NVIDIA's USD as it is (no taxels)
    robot: "robotiq_2f85_tsf"   same + the 7x4 tactile zones of NVIDIA's robotiq-tsf85-contact-twin on each finger
                                 (observation "extra/tactile", shape (2, 7, 4): left / right finger, N)

A different, already built USD can be given with `robot_usd: path/to/file.usda` (no build is done).
Optional finger tuning of the Robotiq profiles: finger_stiffness, finger_damping (None = the values of the USD) and
finger_effort (N.m of the finger joint, the maximum torque of the finger motor = the grip force limit). The Robotiq profiles
now carry finger_effort = 6.0 (the USD's own value is 16.5: with it 10 of 300 reset seeds crushed or lost the peg, with 6
it was 0 of 300; measured with scripts/isaaclab/grip_check.py) and fingerpad_length = 0.0056 (the peg
is held ~12 mm higher than with FORGE's 0.017608, so that the finger collision zones do not reach the socket plate before
the peg is fully in). A YAML field of the same name overrides the profile's value. `tactile_exclude_zone_joints: true` is
the fallback if PhysX complains about the number of links of the articulation (see robot_assets.py).

What a profile carries: where the wrist camera is, how the gripper is commanded, the length of the finger pad that
FORGE uses to place the peg in the hand, whether there are taxels, and how to build the USD. Nothing in here imports
Isaac Sim at module level, so the clients (eval, replay, collection) can import it too.

The NVIDIA files (Robotiq USD, TSF_85.usd, the tactile repository) are NEVER copied or modified: they stay in
expo_ft/third_party/robotiq/ (gitignored) and the derived USD written in assets/robots/ (gitignored) only references them.
"""
from __future__ import annotations

from dataclasses import dataclass, replace
from pathlib import Path
from typing import Optional, Tuple

REPO_ROOT = Path(__file__).resolve().parents[3]

ROBOTIQ_DIR = REPO_ROOT / "expo_ft" / "third_party" / "robotiq"
ROBOTIQ_SOURCE_USD = ROBOTIQ_DIR / "robotiq_usd" / "franka_robotiq_2f_85_flattened.usd"
TSF85_USD = ROBOTIQ_DIR / "robotiq_usd" / "TSF_85.usd"
TACTILE_REPO = ROBOTIQ_DIR / "robotiq-tsf85-contact-twin-main"
ASSETS_DIR = REPO_ROOT / "assets" / "robots"

# Layout of the taxels: 7 rows x 4 columns per finger, row 0 = fingertip end (NVIDIA's convention).
TACTILE_ROWS, TACTILE_COLS = 7, 4


@dataclass(frozen=True)
class WristCamera:
    """Where the wrist camera sits. `mount` is a prim path relative to the robot prim of the scene (Robot/...)."""
    mount: str
    pos: Tuple[float, float, float]
    rot: Tuple[float, float, float, float]       # quaternion (w, x, y, z), in `convention`
    convention: str                              # "ros" (+z forward, +y down) or "opengl" (-z forward, +y up)
    focal_length: float
    horizontal_aperture: Optional[float]         # None = Isaac Lab's default aperture
    # Camera orientation (ROS convention) in the frame of the fingertip: only used by the teleop client to turn
    # "mouse right / up" into directions of the table plane for the wrist view.
    rot_ros_in_fingertip: Tuple[float, float, float, float]


@dataclass(frozen=True)
class RobotProfile:
    name: str
    description: str
    gripper: str                                 # "franka_hand" | "robotiq_2f85"
    wrist_camera: WristCamera
    tactile: bool = False
    build_usd: bool = False                      # True: assets/robots/<name>.usda is generated by robot_assets.py
    robot_usd: Optional[str] = None              # path of an already built USD (overrides the build)
    fingerpad_length: Optional[float] = None     # FORGE's RobotCfg.franka_fingerpad_length (m); None = FORGE's value
    finger_effort: Optional[float] = None        # effort limit of the Robotiq finger joint (N.m); None = the USD's (16.5)


# Franka: the validated camera of forge_env_patched.py (mounted on panda_hand, ROS convention).
_FRANKA_WRIST_ROT = (0.6916, -0.1471, -0.1471, 0.6916)
FRANKA_WRIST = WristCamera(
    mount="panda_hand", pos=(0.05, 0.0, 0.0), rot=_FRANKA_WRIST_ROT, convention="ros",
    focal_length=18.0, horizontal_aperture=None, rot_ros_in_fingertip=_FRANKA_WRIST_ROT)

# Robotiq: the pose of the camera `wrist_camera` that NVIDIA authored on base_link in franka_robotiq_2f_85_flattened.usd
# (measured with usd-core: position in base_link, USD/OpenGL orientation; focal 3.4 mm, horizontal aperture 5.376 mm,
# i.e. 76.6 degrees). Looks at the fingertips from 78 mm behind them, tilted 21 degrees, gripper at the bottom of the
# image and the fingers opening along the image's horizontal axis, like a DROID wrist view.
ROBOTIQ_WRIST = WristCamera(
    mount="robot/Gripper/Robotiq_2F_85/base_link", pos=(-0.00079, 0.02945, 0.07803),
    rot=(0.58535, 0.40493, -0.39748, -0.57915), convention="opengl",
    focal_length=3.4, horizontal_aperture=5.376,
    rot_ros_in_fingertip=(0.69496, -0.12319, -0.13285, 0.69585))

PROFILES = {
    "franka": RobotProfile(
        name="franka", description="Franka + Franka Hand (FORGE's franka_mimic.usd)", gripper="franka_hand",
        wrist_camera=FRANKA_WRIST),
    "robotiq_2f85": RobotProfile(
        name="robotiq_2f85", description="Franka + Robotiq 2F-85 (NVIDIA RoboLab USD, no taxels)", gripper="robotiq_2f85",
        wrist_camera=ROBOTIQ_WRIST, tactile=False, build_usd=True, fingerpad_length=0.0056, finger_effort=6.0),
    "robotiq_2f85_tsf": RobotProfile(
        name="robotiq_2f85_tsf", description="Franka + Robotiq 2F-85 + 7x4 taxels per finger (NVIDIA TSF-85 contact twin)",
        gripper="robotiq_2f85", wrist_camera=ROBOTIQ_WRIST, tactile=True, build_usd=True, fingerpad_length=0.0056,
        finger_effort=6.0),
}


def get_profile(name: str) -> RobotProfile:
    if name not in PROFILES:
        raise ValueError(f"unknown robot {name!r}; the YAML field `robot` must be one of {sorted(PROFILES)}")
    return PROFILES[name]


def profile_from_yaml(cfg: dict) -> RobotProfile:
    """The profile selected by the task YAML (`robot`, default "franka"; `robot_usd` replaces the built USD;
    `fingerpad_length` (m) replaces the profile's value of FORGE's franka_fingerpad_length, which sets how deep the peg
    is held between the fingers at reset: a smaller value holds it higher up, leaving more of the peg below the fingers.
    For one run: forge_server.py --set fingerpad_length=0.0056)."""
    profile = get_profile(str(cfg.get("robot", "franka")))
    if cfg.get("fingerpad_length") is not None:
        profile = replace(profile, fingerpad_length=float(cfg["fingerpad_length"]))
    if cfg.get("robot_usd"):
        if profile.gripper == "franka_hand":
            raise ValueError("robot_usd is for the Robotiq profiles; robot: franka uses FORGE's own USD")
        profile = replace(profile, build_usd=False, robot_usd=str(cfg["robot_usd"]))
    return profile


def robot_info(profile: RobotProfile) -> dict:
    """What a client may want to know about the robot (sent by the server, debug op `robot_info`)."""
    return {
        "name": profile.name, "description": profile.description, "gripper": profile.gripper,
        "finger_effort": profile.finger_effort, "fingerpad_length": profile.fingerpad_length,
        "tactile": profile.tactile, "tactile_shape": [2, TACTILE_ROWS, TACTILE_COLS] if profile.tactile else None,
        "wrist_rot_ros_in_fingertip": list(profile.wrist_camera.rot_ros_in_fingertip),
    }


def apply_to_env_cfg(env_cfg, profile: RobotProfile, usd_path, cfg: dict):
    """Change FORGE's robot config (spawned USD, initial joints, actuators) for a Robotiq profile.

    The two arm actuator groups (panda_arm1 / panda_arm2: same joint names, same limits) are kept, the server sets their
    gains afterwards. The Franka Hand group is replaced by one group for the single driven finger joint (`finger_joint`,
    the five other gripper joints are MIMIC joints that PhysX moves by itself, they get a passive group).
    Stiffness / damping / effort left to None are the values authored in NVIDIA's USD.
    """
    if profile.gripper == "franka_hand":
        return env_cfg
    from isaaclab.actuators import ImplicitActuatorCfg

    robot = env_cfg.robot
    robot.spawn.usd_path = str(usd_path)
    robot.init_state.joint_pos = {k: v for k, v in robot.init_state.joint_pos.items() if k.startswith("panda_joint")}
    arm = {k: v for k, v in robot.actuators.items() if k.startswith("panda_arm")}
    arm["robotiq_finger"] = ImplicitActuatorCfg(
        joint_names_expr=["finger_joint"],
        stiffness=cfg.get("finger_stiffness"), damping=cfg.get("finger_damping"),
        effort_limit_sim=cfg["finger_effort"] if cfg.get("finger_effort") is not None else profile.finger_effort,
        velocity_limit_sim=None)
    arm["robotiq_passive"] = ImplicitActuatorCfg(
        joint_names_expr=["right_outer_knuckle_joint", ".*_inner_finger_joint", ".*_inner_finger_knuckle_joint"],
        stiffness=None, damping=None)
    robot.actuators = arm
    if profile.fingerpad_length is not None:
        env_cfg.task.robot_cfg.franka_fingerpad_length = profile.fingerpad_length
    return env_cfg
